# Nhị phân trên mảng ngắn hơn - O(log(min(m,n)))
def solve(a, b):
    if len(a) > len(b): a, b = b, a
    m, n = len(a), len(b); half = (m + n + 1) // 2
    lo, hi = 0, m
    INF = float('inf')
    while lo <= hi:
        i = (lo + hi) // 2; j = half - i
        aL = a[i-1] if i > 0 else -INF; aR = a[i] if i < m else INF
        bL = b[j-1] if j > 0 else -INF; bR = b[j] if j < n else INF
        if aL <= bR and bL <= aR:
            if (m + n) % 2: return float(max(aL, bL))
            return (max(aL, bL) + min(aR, bR)) / 2.0
        if aL > bR: hi = i - 1
        else: lo = i + 1
a, b = _read(); _out(solve(a, b))

