# Min-heap trên đầu các danh sách liên kết - O(N log k)
import heapq
class ListNode:
    def __init__(s, v=0, n=None): s.val, s.next = v, n
def build(a):
    d = t = ListNode()
    for v in a: t.next = ListNode(v); t = t.next
    return d.next
def dump(h):
    r = []
    while h: r.append(h.val); h = h.next
    return r
def solve(lists):
    heap = [(h.val, i, h) for i, h in enumerate(lists) if h]
    heapq.heapify(heap); d = t = ListNode()
    while heap:
        v, i, node = heapq.heappop(heap)
        t.next = node; t = node
        if node.next: heapq.heappush(heap, (node.next.val, i, node.next))
    return d.next
(ls,) = _read(); _out(dump(solve([build(a) for a in ls])))

