# Đảo từng nhóm k nút tại chỗ - O(n) thời gian, O(1) bộ nhớ
class ListNode:
    def __init__(s, v=0, n=None): s.val, s.next = v, n
def build(a):
    d = t = ListNode()
    for v in a: t.next = ListNode(v); t = t.next
    return d.next
def dump(h):
    r = []
    while h: r.append(h.val); h = h.next
    return r
def solve(head, k):
    d = ListNode(0, head); prev = d
    while True:
        kth = prev
        for _ in range(k):
            kth = kth.next
            if not kth: return d.next
        nxt = kth.next; a, b = prev.next, nxt; cur = prev.next
        while cur is not nxt:
            t = cur.next; cur.next = b; b = cur; cur = t
        prev.next = kth; prev = a
