# Tham lam với quay lui về dấu '*' gần nhất - O(n*m) xấu nhất
def solve(s, p):
    i = j = 0; star = -1; mark = 0
    while i < len(s):
        if j < len(p) and p[j] in (s[i], '?'): i += 1; j += 1
        elif j < len(p) and p[j] == '*': star = j; mark = i; j += 1
