# Tham lam theo từng dòng, chia đều khoảng trắng, dư dồn sang trái
def solve(words, W):
    res = []; i = 0
    while i < len(words):
        j = i; length = 0
        while j < len(words) and length + len(words[j]) + (j - i) <= W:
            length += len(words[j]); j += 1
        gaps = j - i - 1
        if j == len(words) or gaps == 0:
            line = ' '.join(words[i:j]); line += ' ' * (W - len(line))
        else:
            sp, extra = divmod(W - length, gaps); line = ''
            for t in range(i, j - 1):
                line += words[t] + ' ' * (sp + (1 if t - i < extra else 0))
            line += words[j-1]
        res.append(line); i = j
    return res
