    def dfs(i, j, par):
        c = board[i][j]; node = par[c]
        if '$' in node: res.append(node.pop('$'))
        board[i][j] = '#'
        for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
            x, y = i + di, j + dj
            if 0 <= x < R and 0 <= y < C and board[x][y] in node: dfs(x, y, node)
        board[i][j] = c
        if not node: par.pop(c)
    for i in range(R):
        for j in range(C):
