def solve(code):
    st = []; i = 0; n = len(code)
    while i < n:
        if i > 0 and not st: return False            # phải được bọc trong đúng 1 thẻ đóng
        if code.startswith('<![CDATA[', i):
            if not st: return False
            j = code.find(']]>', i + 9)
