            if not st or st[-1] != name: return False
            st.pop(); i = j + 1
        elif code[i] == '<':
            j = code.find('>', i + 1)
            if j < 0: return False
            name = code[i+1:j]
            if not (1 <= len(name) <= 9 and name.isalpha() and name.isupper()): return False
            st.append(name); i = j + 1
        else:
            if not st: return False
            i += 1
    return not st and n > 0
