# Sắp cây theo chiều cao, BFS giữa từng cặp cây liên tiếp - O((RC)^2)
from collections import deque
def solve(f):
    R, C = len(f), len(f[0])
    trees = sorted((f[i][j], i, j) for i in range(R) for j in range(C) if f[i][j] > 1)
    def bfs(sr, sc, tr, tc):
        if (sr, sc) == (tr, tc): return 0
        seen = {(sr, sc)}; q = deque([(sr, sc, 0)])
        while q:
            r, c, d = q.popleft()
            for x, y in ((r+1, c), (r-1, c), (r, c+1), (r, c-1)):
                if 0 <= x < R and 0 <= y < C and f[x][y] and (x, y) not in seen:
                    if (x, y) == (tr, tc): return d + 1
                    seen.add((x, y)); q.append((x, y, d + 1))
        return -1
    r = c = total = 0
    for _, tr, tc in trees:
        d = bfs(r, c, tr, tc)
        if d < 0: return -1
        total += d; r, c = tr, tc
    return total
