# Tìm nút có 2 cha (cand1, cand2); DSU bỏ qua cand2 để phát hiện chu trình
def solve(edges):
    n = len(edges); parent = [0] * (n + 1); c1 = c2 = None
    for u, v in edges:
        if parent[v]: c1 = [parent[v], v]; c2 = [u, v]
        else: parent[v] = u
    root = list(range(n + 1))
    def find(x):
        while root[x] != x: root[x] = root[root[x]]; x = root[x]
        return x
    for u, v in edges:
        if c2 and [u, v] == c2: continue
        ru, rv = find(u), find(v)
        if ru == rv: return c1 if c1 else [u, v]
        root[rv] = ru
    return c2
