# Tổng đoạn độ dài k; best-left/best-right theo chỉ số (ưu tiên từ điển nhỏ) - O(n)
def solve(a, k):
    n = len(a); w = [0] * (n - k + 1); s = sum(a[:k]); w[0] = s
    for i in range(1, n - k + 1): s += a[i + k - 1] - a[i - 1]; w[i] = s
    L = [0] * len(w); R = [0] * len(w); b = 0
    for i in range(len(w)):
        if w[i] > w[b]: b = i
        L[i] = b
    b = len(w) - 1
    for i in range(len(w) - 1, -1, -1):
        if w[i] >= w[b]: b = i
        R[i] = b
    best = None
    for j in range(k, len(w) - k):
        i, l = L[j - k], R[j + k]; t = (w[i] + w[j] + w[l], [i, j, l])
        if best is None or t[0] > best[0]: best = t
    return best[1]
