# DP bitmask trên các ký tự target đã phủ; mỗi bước chỉ dùng sticker chứa ký tự đầu còn thiếu
from collections import Counter
def solve(stickers, target):
    n = len(target); full = (1 << n) - 1
    sc = [Counter(s) for s in stickers]
    dp = [-1] * (1 << n); dp[0] = 0
    for mask in range(1 << n):
        if dp[mask] < 0: continue
        first = next((i for i in range(n) if not mask >> i & 1), None)
        if first is None: continue
        for c in sc:
            if target[first] not in c: continue
            cnt = dict(c); nm = mask
            for i in range(n):
                if not nm >> i & 1 and cnt.get(target[i], 0) > 0:
                    cnt[target[i]] -= 1; nm |= 1 << i
            if dp[nm] < 0 or dp[nm] > dp[mask] + 1: dp[nm] = dp[mask] + 1
    return dp[full]
