import bisect
class RangeModule:
    def __init__(self): self.a = []           # các mốc xen kẽ [l0, r0, l1, r1, ...]
    def addRange(self, l, r):
        i = bisect.bisect_left(self.a, l); j = bisect.bisect_right(self.a, r)
        self.a[i:j] = ([l] if i % 2 == 0 else []) + ([r] if j % 2 == 0 else [])
    def removeRange(self, l, r):
        i = bisect.bisect_left(self.a, l); j = bisect.bisect_right(self.a, r)
        self.a[i:j] = ([l] if i % 2 == 1 else []) + ([r] if j % 2 == 1 else [])
    def queryRange(self, l, r):
        i = bisect.bisect_right(self.a, l); j = bisect.bisect_left(self.a, r)
        return i == j and i % 2 == 1
