def solve(s):
    MOD = 10**9 + 7; n = len(s)
    nxt = [[n] * 4 for _ in range(n + 1)]; prv = [[-1] * 4 for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        nxt[i] = nxt[i + 1][:]; nxt[i][ord(s[i]) - 97] = i
    last = [-1] * 4
