# Tách token, đệ quy với chuỗi scope (list dict) để xử lý biến cục bộ
def solve(expr):
    tokens = expr.replace('(', ' ( ').replace(')', ' ) ').split(); pos = 0
    def parse():
        nonlocal pos
        t = tokens[pos]; pos += 1
        if t != '(': return t
        lst = []
        while tokens[pos] != ')': lst.append(parse())
        pos += 1; return lst
    def ev(e, scope):
        if isinstance(e, str):
            if e[0] in '-0123456789': return int(e)
            for sc in reversed(scope):
                if e in sc: return sc[e]
        op = e[0]
        if op == 'add': return ev(e[1], scope) + ev(e[2], scope)
        if op == 'mult': return ev(e[1], scope) * ev(e[2], scope)
        scope = scope + [{}]
        for i in range(1, len(e) - 1, 2): scope[-1][e[i]] = ev(e[i + 1], scope)
        return ev(e[-1], scope)
    return ev(parse(), [])
