# Hai người đi cùng lúc từ (0,0) tới (n-1,n-1): dp[t][r1][r2] - O(n^3)
def solve(g):
    n = len(g); NEG = float('-inf')
    dp = [[NEG] * n for _ in range(n)]; dp[0][0] = g[0][0]
    for t in range(1, 2 * n - 1):
        nd = [[NEG] * n for _ in range(n)]
        for r1 in range(max(0, t - n + 1), min(n, t + 1)):
            c1 = t - r1
            if g[r1][c1] < 0: continue
            for r2 in range(r1, min(n, t + 1)):
                c2 = t - r2
                if g[r2][c2] < 0: continue
                best = max(dp[r1][r2], dp[r1 - 1][r2] if r1 else NEG,
                           dp[r1][r2 - 1] if r2 else NEG, dp[r1 - 1][r2 - 1] if r1 and r2 else NEG)
                if best == NEG: continue
                nd[r1][r2] = best + g[r1][c1] + (g[r2][c2] if r1 != r2 else 0)
        dp = nd
    return max(0, dp[n - 1][n - 1])
