def solve(n, k):
    if n == 1: return ''.join(str(i) for i in range(k))
    seen = set(); res = []; start = '0' * (n - 1); st = [(start, iter(range(k)))]
    while st:
        node, it = st[-1]; moved = False
        for x in it:
            e = node + str(x)
            if e not in seen:
                seen.add(e); st.append((e[1:], iter(range(k))))
