def solve(edges, maxMoves, n):
    g = [[] for _ in range(n)]
    for u, v, c in edges: g[u].append((v, c + 1)); g[v].append((u, c + 1))
    INF = float('inf'); d = [INF] * n; d[0] = 0; pq = [(0, 0)]
