                    disc[v] = low[v] = t; t += 1; st.append((v, e, iter(g[v]))); moved = True; break
                low[u] = min(low[u], disc[v])
            if not moved:
                st.pop()
                if st:
                    p = st[-1][0]; low[p] = min(low[p], low[u])
                    if low[u] > disc[p]: res.append(sorted([p, u]))
