def topo(nodes, edges):
    indeg = {u: 0 for u in nodes}
    for u in nodes:
        for v in edges[u]: indeg[v] += 1
    q = deque(sorted(u for u in nodes if indeg[u] == 0)); out = []
    while q:
        u = q.popleft(); out.append(u)
