# 0-1 BFS: đi theo mũi tên tốn 0, đổi hướng tốn 1 - O(RC)
from collections import deque
def solve(g):
    R, C = len(g), len(g[0]); D = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    dist = [[1 << 30] * C for _ in range(R)]; dist[0][0] = 0; dq = deque([(0, 0, 0)])
    while dq:
        d, r, c = dq.popleft()
        if d > dist[r][c]: continue
        for k, (dr, dc) in enumerate(D):
            x, y = r + dr, c + dc
            if 0 <= x < R and 0 <= y < C:
                w = 0 if g[r][c] == k + 1 else 1
                if d + w < dist[x][y]:
                    dist[x][y] = d + w
                    (dq.appendleft if w == 0 else dq.append)((d + w, x, y))
    return dist[R - 1][C - 1]
(g,) = _read(); _out(solve(g))

