# Hậu thứ tự trả về (là BST?, min, max, tổng) - O(n), duyệt lặp
from collections import deque
class TreeNode:
    def __init__(s, v): s.val = v; s.left = s.right = None
def build(a):
    if not a or a[0] is None: return None
    root = TreeNode(a[0]); q = deque([root]); i = 1
    while q and i < len(a):
        u = q.popleft()
        if i < len(a) and a[i] is not None: u.left = TreeNode(a[i]); q.append(u.left)
        i += 1
        if i < len(a) and a[i] is not None: u.right = TreeNode(a[i]); q.append(u.right)
        i += 1
    return root
def solve(root):
    INF = float('inf'); info = {None: (True, INF, -INF, 0)}; best = 0; st = [(root, False)]
    while st:
        u, done = st.pop()
        if not u: continue
        if not done: st += [(u, True), (u.left, False), (u.right, False)]; continue
        lb, lmn, lmx, ls = info[u.left]; rb, rmn, rmx, rs = info[u.right]
        if lb and rb and lmx < u.val < rmn:
            s = ls + rs + u.val; best = max(best, s)
            info[u] = (True, min(lmn, u.val), max(rmx, u.val), s)
        else: info[u] = (False, 0, 0, 0)
    return best
(a,) = _read(); _out(solve(build(a)))

