# BFS/DFS từ 1 nhân xác suất; ếch dừng khi hết thời gian hoặc ở lá - O(n)
def solve(n, edges, t, target):
    g = [[] for _ in range(n + 1)]
    for a, b in edges: g[a].append(b); g[b].append(a)
    st = [(1, 0, 0, 1.0)]
    while st:
        u, par, time, p = st.pop()
        kids = [v for v in g[u] if v != par]
        if u == target: return p if time == t or (time < t and not kids) else 0.0
        if time < t:
            for v in kids: st.append((v, u, time + 1, p / len(kids)))
    return 0.0
