# Sắp theo efficiency giảm dần, min-heap giữ k tốc độ lớn nhất - O(n log n)
import heapq
def solve(n, speed, eff, k):
    h = []; s = best = 0
    for e, sp in sorted(zip(eff, speed), reverse=True):
        heapq.heappush(h, sp); s += sp
        if len(h) > k: s -= heapq.heappop(h)
        best = max(best, s * e)
    return best % (10**9 + 7)
