    def line(a):
        m = len(a); dp = [[0] * (n + 1) for _ in range(m + 2)]
        for i in range(m - 1, -1, -1):
            for k in range(1, n + 1):
                dp[i][k] = max(dp[i + 1][k], a[i] + dp[i + 2][k - 1])
        return dp[0][n]
    return max(line(s[1:]), line(s[:-1]))
