# Hàm tiền tố KMP: pi[n-1] là độ dài tiền tố = hậu tố dài nhất - O(n)
def solve(s):
    pi = [0] * len(s)
    for i in range(1, len(s)):
        k = pi[i - 1]
        while k and s[i] != s[k]: k = pi[k - 1]
        if s[i] == s[k]: k += 1
        pi[i] = k
    return s[:pi[-1]] if s else ''
