def solve(s, k):
    MOD = 10**9 + 7; n = len(s); dp = [0] * (n + 1); dp[n] = 1; L = len(str(k))
    for i in range(n - 1, -1, -1):
        if s[i] == '0': continue
        for j in range(i + 1, min(n, i + L) + 1):
            if int(s[i:j]) > k: break
            dp[i] += dp[j]
        dp[i] %= MOD
    return dp[0]
