# dp[i][max][cost] với tổng tiền tố theo max - O(n * m * k)
def solve(n, m, k):
    MOD = 10**9 + 7
    dp = [[0] * (k + 1) for _ in range(m + 1)]
    for v in range(1, m + 1): dp[v][1] = 1
    for _ in range(1, n):
        nd = [[0] * (k + 1) for _ in range(m + 1)]
        for c in range(1, k + 1):
            pref = 0
            for v in range(1, m + 1):
                nd[v][c] = (dp[v][c] * v + pref) % MOD       # giữ max v, hoặc max mới là v
                pref = (pref + dp[v][c - 1]) % MOD if c > 1 else 0
        dp = nd
    return sum(dp[v][k] for v in range(1, m + 1)) % MOD
