# DP + deque đơn điệu giảm lấy max dp trong cửa sổ k - O(n)
from collections import deque
def solve(a, k):
    dp = a[:]; dq = deque()
    for i in range(len(a)):
        if dq: dp[i] += max(0, dp[dq[0]])
        while dq and dp[dq[-1]] <= dp[i]: dq.pop()
        dq.append(i)
        if dq[0] <= i - k: dq.popleft()
    return max(dp)
