# DP theo mũ (40) với bitmask người (<= 10) - O(40 * 2^n * n)
def solve(hats):
    MOD = 10**9 + 7; n = len(hats); who = [[] for _ in range(41)]
    for p, hs in enumerate(hats):
        for h in hs: who[h].append(p)
    dp = [0] * (1 << n); dp[0] = 1
    for h in range(1, 41):
        for m in range((1 << n) - 1, -1, -1):
            if not dp[m]: continue
            for p in who[h]:
                if not m >> p & 1: dp[m | 1 << p] = (dp[m | 1 << p] + dp[m]) % MOD
    return dp[-1]
