# Tổng hậu tố số táo; dp[k][i][j] = số cách cắt phần (i..,j..) thành k miếng - O(k R C (R+C))
def solve(pizza, k):
    MOD = 10**9 + 7; R, C = len(pizza), len(pizza[0])
    A = [[0] * (C + 1) for _ in range(R + 1)]
    for i in range(R - 1, -1, -1):
        for j in range(C - 1, -1, -1):
            A[i][j] = (pizza[i][j] == 'A') + A[i+1][j] + A[i][j+1] - A[i+1][j+1]
    dp = [[1 if A[i][j] else 0 for j in range(C)] for i in range(R)]
    for _ in range(1, k):
        nd = [[0] * C for _ in range(R)]
        for i in range(R):
            for j in range(C):
                v = 0
                for x in range(i + 1, R):
                    if A[i][j] - A[x][j] > 0: v += dp[x][j]
                for y in range(j + 1, C):
                    if A[i][j] - A[i][y] > 0: v += dp[i][y]
                nd[i][j] = v % MOD
        dp = nd
    return dp[0][0]
