# dp[t] = số chữ số tối đa với chi phí đúng t; dựng tham lam chữ số lớn trước - O(9 * target)
def solve(cost, target):
    NEG = float('-inf'); dp = [0] + [NEG] * target
    for t in range(1, target + 1):
        for c in cost:
            if c <= t and dp[t - c] + 1 > dp[t]: dp[t] = dp[t - c] + 1
    if dp[target] < 0: return '0'
    res = []; t = target
    for d in range(9, 0, -1):
        c = cost[d - 1]
        while c <= t and dp[t] == dp[t - c] + 1: res.append(str(d)); t -= c
    return ''.join(res)
