# Với mỗi cặp điểm, xét 2 tâm đường tròn bán kính r qua cả hai; đếm điểm bên trong - O(n^3)
from math import sqrt
def solve(pts, r):
    n = len(pts); best = 1; eps = 1e-7
    def count(cx, cy): return sum((x - cx) ** 2 + (y - cy) ** 2 <= r * r + eps for x, y in pts)
    for i in range(n):
        for j in range(i + 1, n):
            (x1, y1), (x2, y2) = pts[i], pts[j]
            d2 = (x1 - x2) ** 2 + (y1 - y2) ** 2
            if d2 > 4 * r * r: continue
            mx, my = (x1 + x2) / 2, (y1 + y2) / 2; h = sqrt(max(0.0, r * r - d2 / 4)); d = sqrt(d2)
            ox, oy = -(y2 - y1) / d * h, (x2 - x1) / d * h
            best = max(best, count(mx + ox, my + oy), count(mx - ox, my - oy))
    return best
