# dp[c1][c2] theo từng hàng cho hai robot - O(R * C^2 * 9)
def solve(g):
    R, C = len(g), len(g[0]); NEG = float('-inf')
    dp = [[NEG] * C for _ in range(C)]; dp[0][C - 1] = g[0][0] + (g[0][C-1] if C > 1 else 0)
    for r in range(1, R):
        nd = [[NEG] * C for _ in range(C)]
        for a in range(C):
            for b in range(C):
                if dp[a][b] == NEG: continue
                for na in (a - 1, a, a + 1):
                    for nb in (b - 1, b, b + 1):
                        if 0 <= na < C and 0 <= nb < C:
                            v = dp[a][b] + g[r][na] + (g[r][nb] if na != nb else 0)
                            if v > nd[na][nb]: nd[na][nb] = v
        dp = nd
    return max(map(max, dp))
