# Duyệt số bi mỗi màu vào hộp 1, đếm cách bằng tổ hợp (chính xác bằng số nguyên) - O(prod(b+1))
from math import comb
def solve(balls):
    total = sum(balls); half = total // 2; good = allw = 0
    def dfs(i, n1, d1, d2, ways):
        nonlocal good, allw
        if n1 > half: return
        if i == len(balls):
            if n1 == half:
                allw += ways
                if d1 == d2: good += ways
            return
        for x in range(balls[i] + 1):
            dfs(i + 1, n1 + x, d1 + (x > 0), d2 + (x < balls[i]), ways * comb(balls[i], x))
