# Kruskal nhiều lần: bỏ cạnh làm MST tăng -> critical; ép dùng cạnh mà không tăng -> pseudo - O(E^2 α)
def solve(n, edges):
    E = sorted(range(len(edges)), key=lambda i: edges[i][2])
    def mst(skip=-1, force=-1):
        par = list(range(n))
        def find(x):
            while par[x] != x: par[x] = par[par[x]]; x = par[x]
            return x
        w = cnt = 0
        if force >= 0:
            u, v, c = edges[force]; par[find(u)] = find(v); w += c; cnt = 1
        for i in E:
            if i == skip: continue
            u, v, c = edges[i]; a, b = find(u), find(v)
            if a != b: par[a] = b; w += c; cnt += 1
        return w if cnt == n - 1 else float('inf')
    base = mst(); crit = []; pseudo = []
    for i in range(len(edges)):
        if mst(skip=i) > base: crit.append(i)
        elif mst(force=i) == base: pseudo.append(i)
    return [crit, pseudo]
