# Hai DSU (Alice, Bob); ưu tiên cạnh loại 3 trước - O(E α)
class DSU:
    def __init__(s, n): s.p = list(range(n + 1)); s.c = n
    def find(s, x):
        while s.p[x] != x: s.p[x] = s.p[s.p[x]]; x = s.p[x]
        return x
    def union(s, a, b):
        a, b = s.find(a), s.find(b)
        if a == b: return False
        s.p[a] = b; s.c -= 1; return True
