            for s in range(1, jump + 1):
                x, y = r + dr * s, c + dc * s
                if not (0 <= x < R and 0 <= y < C) or grid[x][y] == '#': break
                res.append(x * C + y)
        return res
    mm = [moves(p, mouseJump) if grid[p // C][p % C] != '#' else [] for p in range(N)]
    cm = [moves(p, catJump) if grid[p // C][p % C] != '#' else [] for p in range(N)]
    MOUSE, CAT = 1, 2
    res = [[[0, 0] for _ in range(N)] for _ in range(N)]
    deg = [[[len(mm[m]), len(cm[c])] for c in range(N)] for m in range(N)]
    q = deque()
