            if (pt == 0 and r == MOUSE) or (pt == 1 and r == CAT):
                res[pm][pc][pt] = r; q.append((pm, pc, pt))
            else:
                deg[pm][pc][pt] -= 1
                if deg[pm][pc][pt] == 0: res[pm][pc][pt] = r; q.append((pm, pc, pt))
