    for t in trees:
        for c in (t.left, t.right):
            if c: leaves.add(c.val)
    cand = [t for t in trees if t.val not in leaves]
    if len(cand) != 1: return None
    root = cand[0]; del roots[root.val]
    st = [(root, float('-inf'), float('inf'))]
    while st:
        u, lo, hi = st.pop()
        if not lo < u.val < hi: return None
        if not u.left and not u.right and u.val in roots and u is not root:
            t = roots.pop(u.val); u.left, u.right = t.left, t.right
        if u.left: st.append((u.left, lo, u.val))
        if u.right: st.append((u.right, u.val, hi))
