        e = i + d[i] - 1; pre[e] = max(pre[e], 2 * d[i] - 1)
        st = i - d[i] + 1; suf[st] = max(suf[st], 2 * d[i] - 1)
    for i in range(n - 2, -1, -1): pre[i] = max(pre[i], pre[i + 1] - 2)   # co palindrome lại 1 ký tự mỗi bên
    for i in range(1, n): pre[i] = max(pre[i], pre[i - 1])
    for i in range(1, n): suf[i] = max(suf[i], suf[i - 1] - 2)
    for i in range(n - 2, -1, -1): suf[i] = max(suf[i], suf[i + 1])
