# Hai heap: heap tối đa giữ các vị trí đã trả về, heap tối thiểu giữ phần còn lại
class Name:
    __slots__ = 'n'
    def __init__(self, n): self.n = n
    def __lt__(self, o): return self.n > o.n
    def __eq__(self, o): return self.n == o.n
class SORTracker:
    def __init__(self): self.top = []; self.rest = []
    def add(self, name, score):
        heapq.heappush(self.top, (score, Name(name)))   # min-heap: phần tử tệ nhất trong top ở đỉnh
        s, nm = heapq.heappop(self.top)
        heapq.heappush(self.rest, (-s, nm.n))
    def get(self):
        s, name = heapq.heappop(self.rest)
        heapq.heappush(self.top, (-s, Name(name)))
        return name
