from collections import Counter
def solve(words):
    cnt = Counter(sum(1 << (ord(c) - 97) for c in w) for w in words)
    par = {m: m for m in cnt}
    def find(x):
        while par[x] != x: par[x] = par[par[x]]; x = par[x]
        return x
    def union(a, b): par[find(a)] = find(b)
