def solve(nums, slots):
    p3 = [3 ** i for i in range(slots + 1)]; dp = [-1] * p3[slots]; dp[0] = 0; best = 0
    for m in range(p3[slots]):
        if dp[m] < 0: continue
        used = 0; x = m
        for _ in range(slots): used += x % 3; x //= 3
