from collections import deque
def solve(g):
    R, C = len(g), len(g[0]); INF = 10**9; D = ((1, 0), (-1, 0), (0, 1), (0, -1))
    fire = [[INF] * C for _ in range(R)]; q = deque()
    for i in range(R):
        for j in range(C):
            if g[i][j] == 1: fire[i][j] = 0; q.append((i, j))
    while q:
        r, c = q.popleft()
        for dr, dc in D:
            x, y = r + dr, c + dc
            if 0 <= x < R and 0 <= y < C and g[x][y] == 0 and fire[x][y] == INF:
                fire[x][y] = fire[r][c] + 1; q.append((x, y))
    def can(wait):
        if wait >= fire[0][0]: return False
        seen = [[False] * C for _ in range(R)]; seen[0][0] = True; q = deque([(0, 0, wait)])
        while q:
            r, c, t = q.popleft()
            for dr, dc in D:
                x, y = r + dr, c + dc
                if 0 <= x < R and 0 <= y < C and g[x][y] == 0 and not seen[x][y]:
                    if (x, y) == (R - 1, C - 1): return t + 1 <= fire[x][y]
                    if t + 1 < fire[x][y]: seen[x][y] = True; q.append((x, y, t + 1))
        return False
    if not can(0): return -1
    if can(R * C + 1): return 10**9
    lo, hi = 0, R * C
    while lo < hi:
        m = (lo + hi + 1) // 2
        if can(m): lo = m
        else: hi = m - 1
    return lo
