def solve(nums, edges):
    n = len(nums); g = [[] for _ in range(n)]
    for a, b in edges: g[a].append(b); g[b].append(a)
    xr = nums[:]; tin = [0] * n; tout = [0] * n; par = [-1] * n; t = 0
    st = [(0, False)]; seen = [False] * n
    while st:
        u, done = st.pop()
