            continue
        seen[u] = True; tin[u] = t; t += 1; st.append((u, True))
        for v in g[u]:
            if not seen[v]: par[v] = u; st.append((v, False))
    total = xr[0]; best = float('inf'); anc = lambda a, b: tin[a] <= tin[b] and tout[b] <= tout[a]
    for i in range(1, n):
        for j in range(i + 1, n):
            if anc(i, j): x, y, z = xr[j], xr[i] ^ xr[j], total ^ xr[i]
            elif anc(j, i): x, y, z = xr[i], xr[j] ^ xr[i], total ^ xr[j]
            else: x, y, z = xr[i], xr[j], total ^ xr[i] ^ xr[j]
