def solve(s, k, minL):
    MOD = 10**9 + 7; P = set('2357'); n = len(s)
    if s[0] not in P or s[-1] in P: return 0
    ok = [i == 0 or (s[i] in P and s[i - 1] not in P) for i in range(n)]   # vị trí bắt đầu đoạn
    dp = [1 if i == 0 else 0 for i in range(n + 1)]                          # dp[i]: tiền tố dài i kết thúc đúng một đoạn
    # biểu diễn: f[i] = số cách chia s[:i] thành j đoạn
    f = [0] * (n + 1); f[0] = 1
    for _ in range(k):
        g = [0] * (n + 1); acc = 0
        for i in range(1, n + 1):
            st = i - minL
            if st >= 0 and ok[st]: acc = (acc + f[st]) % MOD
            if i == n or ok[i]: g[i] = acc
        f = g
    return f[n]
