from collections import deque
def solve(n, edges):
    g = [[] for _ in range(n + 1)]
    for a, b in edges: g[a].append(b); g[b].append(a)
    def bfs(s):
        d = {s: 1}; q = deque([s]); mx = 1
        while q:
            u = q.popleft()
            for v in g[u]:
                if v not in d: d[v] = d[u] + 1; mx = max(mx, d[v]); q.append(v)
                elif abs(d[v] - d[u]) != 1: return -1, d
        return mx, d
    comp_best = {}; comp_of = {}
    for s in range(1, n + 1):
        mx, d = bfs(s)
        if mx == -1: return -1
        key = min(d); comp_best[key] = max(comp_best.get(key, 0), mx)
    return sum(comp_best.values())
