from collections import Counter
def solve(a, b):
    n = len(a); cnt = Counter(); total = cost = 0
    for i in range(n):
        if a[i] == b[i]: cnt[a[i]] += 1; total += 1; cost += i
    if not total: return 0
    v, m = cnt.most_common(1)[0]
    need = 2 * m - total
    for i in range(n):
        if need <= 0: break
        if a[i] != b[i] and a[i] != v and b[i] != v: cost += i; need -= 1
    return cost if need <= 0 else -1
