import heapq
def solve(g, queries):
    R, C = len(g), len(g[0]); seen = [[False] * C for _ in range(R)]; seen[0][0] = True
    h = [(g[0][0], 0, 0)]; got = 0; res = [0] * len(queries)
    for qi in sorted(range(len(queries)), key=lambda i: queries[i]):
        q = queries[qi]
        while h and h[0][0] < q:
            _, r, c = heapq.heappop(h); got += 1
            for x, y in ((r+1, c), (r-1, c), (r, c+1), (r, c-1)):
                if 0 <= x < R and 0 <= y < C and not seen[x][y]:
                    seen[x][y] = True; heapq.heappush(h, (g[x][y], x, y))
        res[qi] = got
    return res
