def solve(n, edges):
    adj = [set() for _ in range(n + 1)]
    for a, b in edges: adj[a].add(b); adj[b].add(a)
    odd = [i for i in range(1, n + 1) if len(adj[i]) % 2]
    if not odd: return True
    if len(odd) == 2:
        a, b = odd
        if b not in adj[a]: return True
        return any(c not in adj[a] and c not in adj[b] for c in range(1, n + 1) if c != a and c != b)
    if len(odd) == 4:
        a, b, c, d = odd
        return any(y not in adj[x] and w not in adj[z] for x, y, z, w in ((a, b, c, d), (a, c, b, d), (a, d, b, c)))
    return False
