# Đếm phần bù: tập con có tổng < k (knapsack đếm), trừ 2 lần khỏi 2^n - O(n k)
def solve(a, k):
    MOD = 10**9 + 7
    if sum(a) < 2 * k: return 0
    dp = [1] + [0] * (k - 1)
    for x in a:
        for s in range(k - 1, x - 1, -1): dp[s] = (dp[s] + dp[s - x]) % MOD
    return (pow(2, len(a), MOD) - 2 * sum(dp)) % MOD
