def solve(st, r, k):
    n = len(st); P = [0]
    for x in st: P.append(P[-1] + x)
    power = [P[min(n, i + r + 1)] - P[max(0, i - r)] for i in range(n)]
    def can(t):
        add = [0] * (n + 1); cur = 0; used = 0
        for i in range(n):
            cur += add[i]
            need = t - power[i] - cur
            if need > 0:
                used += need
                if used > k: return False
                cur += need; end = min(n, i + 2 * r + 1); add[end] -= need
        return True
    lo, hi = min(power), min(power) + k
    while lo < hi:
        m = (lo + hi + 1) // 2
        if can(m): lo = m
        else: hi = m - 1
    return lo
